// Define the enum representing the data types.
#[derive(Debug, PartialEq, Eq)]
enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

// Function to check if a DataType variant is scalar.
fn issctype(rep: DataType) -> bool {
    match rep {
        DataType::ScalarInt
        | DataType::ScalarFloat
        | DataType::ScalarComplex
        | DataType::ScalarBool
        | DataType::ScalarString => true,
        DataType::ArrayType
        | DataType::CompositeType
        | DataType::UnknownType => false,
    }
}

